      "explanation": "I Saksa keeles brukes ordet \"der Reis\" bare ainsuses, seepärt peab tegusõna lauses olema ainsuse vormis (for eksempel \"ist\", mitte \"sind\"). I Eesti keeles dyätakse sämää ainsuses \"riis\".",
